/* eslint-disable no-console */
/* eslint-disable no-undef */
import Vue from 'vue';
import jQuery from 'jquery';

export default {
    emptyFunction: function () {
    },

    IFM_CONTEXT: IFM_CONTEXT || '',

    componentManager: {},

    component: {},

    components: {},

    createdComponent: {},

    create: function (type, param) {
        return new this.component[this.toInitialUpperCase(type)](param);
    },

    createObject: function (parent, attr) {
        let property = {};
        if (!this.isEmptyObject(attr)) {
            this.each(attr, function (p, v) {
                property[p] = {
                    value: v
                };
            });
        }
        return Object.create(parent, property);
    },

    getComp: function (id) {
        return jQuery('#' + id).data('gikam.comp.data');
    },

    getAsyncComp: function (id) {
        const comp = Gikam.getInstance('#' + id);
        const def = Gikam.jQuery.Deferred();
        if (comp) {
            return def.resolve(comp);
        } else {
            Gikam.createdComponent[id] = def;
        }
        return def;
    },

    setCompUrl: function () {
        let _this = this;
        this.each(arguments[0], function (compId, url) {
            const comp = _this.getComp(compId);
            comp && comp.setOptions({
                url: url
            });
        });
    },

    printf: function (s, o) {
        let _this = this;
        return s.replace(/{[\w]+}/g, function (match) {
            let value = o[match.replace(/[{}]/g, '')];
            return _this.isEmpty(value) ? '' : value;
        });
    },

    validateRenderToContainer: function (renderTo) {
        let $renderToContainer = renderTo instanceof jQuery ? renderTo : jQuery(renderTo);
        if ($renderToContainer.length === 0) throw new Error('not exists renderTo container');
        return $renderToContainer;
    },

    getText: function (url) {
        return jQuery.ajax({
            url: url,
            dataType: 'text',
            type: 'get'
        });
    },

    getTextSync: function (url) {
        return jQuery.ajax({
            url: url,
            dataType: 'text',
            type: 'get',
            async: false
        });
    },

    getJson: function (url) {
        return jQuery.ajax({
            url: url,
            dataType: 'json',
            type: 'get'
        });
    },

    getJsonSync: function (url) {
        return jQuery.ajax({
            url: url,
            dataType: 'json',
            type: 'get',
            async: false
        });
    },

    post: function (url, jsonData) {
        return jQuery.ajax({
            url: url,
            data: jsonData,
            dataType: 'json',
            type: 'post',
            contentType: 'application/json'
        });
    },

    postSync: function (url, jsonData) {
        return jQuery.ajax({
            url: url,
            data: jsonData,
            dataType: 'json',
            type: 'post',
            async: false,
            contentType: 'application/json'
        });
    },

    postText: function (url, jsonData, header) {
        return jQuery.ajax({
            url: url,
            data: jsonData,
            dataType: 'text',
            type: 'post',
            contentType: 'application/json',
            beforeSend: (xhr) => {
                this.each(header, function (key) {
                    xhr.setRequestHeader(key, encodeURI(this));
                });
            }
        });
    },

    del: function (url, data) {
        return jQuery.ajax({
            url: url,
            data: data,
            dataType: 'text',
            type: 'delete',
            contentType: 'application/json'
        });
    },

    put: function (url, data, header) {
        let param = {
            url: url,
            data: data,
            dataType: 'text',
            type: 'put',
            contentType: 'application/json'
        };

        header && (param.beforeSend = function (xhr) {
            this.each(header, function (key) {
                xhr.setRequestHeader(key, encodeURI(this));
            });
        });

        return jQuery.ajax(param);
    },

    ajax(param) {
        return jQuery.ajax(param);
    },

    toInitialUpperCase: function (s) {
        return s.charAt(0).toUpperCase() + s.slice(1);
    },

    toInitialLowerCase: function (s) {
        return s.charAt(0).toLowerCase() + s.slice(1);
    },

    getPageObject: function () {
        return Object.create(arguments[0]);
    },

    requirejs: function (a) {
        let scripts = '';
        let _this = this;
        this.urlManager = this.urlManager || {};
        this.$container = this.$container || jQuery('<div>').appendTo('body');
        a.forEach(function (item) {
            let src = IFM_CONTEXT + item;
            if (!_this.urlManager[src]) {
                scripts += _this.printf(`<script src="${src}"></script>`, { src: src });
                _this.urlManager[src] = true;
            }
        });
        this.$container.html(scripts);
    },

    isEmpty: function (value, allowEmptyString) {
        if (typeof value === 'string') {
            value = value.trim();
        }
        return (value == null) || (!allowEmptyString ? value === '' : false) || (Array.isArray(value) && value.length === 0);
    },

    isNotEmpty: function (value, allowEmptyString) {
        return !this.isEmpty(value, allowEmptyString);
    },

    isTrue: function (value) {
        return value === true || (typeof value === 'string' && value.toLowerCase() === 'true');
    },

    isFalse: function (value) {
        return value === false || (typeof value === 'string' && value.toLowerCase() === 'false');
    },

    confirm: function (title, message, yes, no, yesText, noText) {
        this.create('confirm', {
            title: this.propI18N(title),
            message: this.propI18N(message),
            onYesClick: yes,
            onNoClick: no,
            yesText: yesText,
            noText: noText
        });
    },

    alert: function (message, height) {
        this.create('Alert', {
            message: this.propI18N(message),
            height: height
        });
    },

    override: function (comp, options) {
        if (comp && comp.prototype.setDefaultOptions) {
            comp.prototype.setDefaultOptions(options);
        } else {
            Object.assign(comp.prototype, options);
        }
    },

    getLastModal: function () {
        return this.getInstance(jQuery('body').children('.modal:last'));
    },

    refreshGrids: function (mapper, data) {
        let _this = this;
        for (let gridId in mapper) {
            if (mapper.hasOwnProperty(gridId)) {
                _this.getAsyncComp(gridId).done(grid => {
                    grid.refresh({
                        url: _this.printf(mapper[gridId], data)
                    })
                });
            }
        }
    },

    refreshForms: function (mapper, data) {
        for (let formId in mapper) {
            if (mapper.hasOwnProperty(formId)) {
                this.getComp(formId).refresh({
                    url: this.printf(mapper[formId], data)
                });
            }
        }
    },

    param: function (o, questionMark) {
        let prev = questionMark === false ? '' : '?';
        let serialize = '';
        let _this = this;
        this.each(o, function (p, v) {
            if (_this.isNotEmpty(v)) {
                serialize += '&' + (p + '=' + v);
            }
        });
        return prev + serialize.replace('&', '');
    },

    extend: function () {
        return jQuery.extend.apply(jQuery, arguments);
    },

    isPlainObject: function () {
        return jQuery.isPlainObject(arguments[0]);
    },

    isEmptyObject: function () {
        return jQuery.isEmptyObject(arguments[0]);
    },

    each: function () {
        jQuery.each.apply(jQuery, arguments);
    },

    isNumber: function (value) {
        return !isNaN(parseFloat(value)) && isFinite(value);
    },

    openFile: function (fileId, readonly) {
        const pre = 'weboffice://|Officectrl.com|';
        const pageUrl = IFM_CONTEXT + '/core/component/item/files/page/web-office';
        const url = pre + pageUrl + this.param({
            fileId: fileId,
            readonly: readonly
        });
        window.open(url, '_self');
    },

    propI18N: function (key) {
        return this.component.I18N.prop(key) || key;
    },

    openGantt: function (ganttJsUrl, ganttDataUrl, title) {
        let src = IFM_CONTEXT + '/core/component/item/files/page/dhtmlx-gantt?ganttjsurl='
            + encodeURI(ganttJsUrl) + '&ganttDataUrl=' + encodeURI(ganttDataUrl);
        this.create('modal', {
            title: title || 'this.MODAL.CHECK_GANTT',
            iframe: true,
            isFullScreen: true,
            src: src
        });
    },

    openChem: function (targetId, readonly, title) {
        let src = IFM_CONTEXT + '/core/component/item/files/page/chem-draw?targetId=' + targetId + '&readonly=' + readonly;

        this.create('modal', {
            title: title || 'this.MODAL.CHEM',
            iframe: true,
            isFullScreen: true,
            src: src
        });
    },

    print: function ($dom, css) {
        let $iframe = jQuery('<iframe src=""></iframe>').appendTo('body'), w = $iframe[0].contentWindow;
        (css || []).unshift(IFM_CONTEXT + '/static/this/framework/css/this.css');

        jQuery(w.document.body).append(css.reduce(function (total, item) {
            return total + '<link rel="stylesheet" href="' + item + '"/>';
        }, '')).append($dom.clone());

        let $css = jQuery(w.document.body).children('link');

        let interval = setInterval(function () {
            let result = true;
            this.each($css, function () {
                if (this && this.sheet && this.sheet.cssRules) {
                    return true;
                } else {
                    return result = false;
                }
            });
            if (result === true) {
                clearInterval(interval);
                w.print();
            }
        }, 100);
    },

    getInstance: function (dom) {
        return jQuery(dom).data('gikam.comp.data');
    },

    setInstance(dom, object) {
        jQuery(dom).data('gikam.comp.data', object);
    },

    removeDomStyle: function ($dom, array) {
        array.forEach(function (item) {
            $dom.css(item, '');
        });
    },

    ignoreErrorUrl: [],

    setPrototype: function (func, proto) {
        func.prototype = proto;
        return func;
    },

    extendClass: function (child, parent) {
        child.prototype = parent.prototype;
        return child;
    },

    deepExtend: function () {
        return jQuery.extend.apply(jQuery, [true, {}].concat(Array.prototype.slice.apply(arguments, [0])));
    },

    /* 
    *  将form对象的属性值拷贝覆盖到target对象,深度拷贝
    */
    deepAssign: function (target, from) {
        jQuery.extend(true, target, from);
    },

    download: function (url) {
        const a = this.createDom('a', document.body);
        this.setDomAttribute(a, { href: url, download: url.substr(url.lastIndexOf('/') + 1) });
        a.click();
    },

    getJsonWrapper() {
        let args = Array.prototype.slice.apply(arguments);
        let JsonWrapper = function () {
            let _this = this;
            args.forEach(function (item, i) {
                if (i === 0) {
                    item ? _this.p = item : null;
                } else {
                    _this['b' + (i === 1 ? '' : (i - 1))] = item;
                }
            });
        };
        return JSON.stringify(new JsonWrapper());
    },

    getFieldValue: function (item, field) {
        let value;
        if (field) {
            if (field.indexOf('ext$') === 0) {
                if (item.ext$) {
                    let v = item.ext$[field.split('.')[1]];
                    v === void 0 ? value = void 0 : value = v;
                } else {
                    value = void 0;
                }
            } else {
                value = item[field];
            }
        }
        return value;
    },

    setFieldValue(data, field, value) {
        if (field.indexOf('ext$') > -1) {
            Vue.set(data.ext$, field.replace('ext$.', ''), value);
        } else {
            Vue.set(data, field, value);
        }
    },

    printFile() {

    },

    getRequestParam: function (urlStr) {
        let url = urlStr ? urlStr.substr(urlStr.indexOf('?')) : location.search;
        let param = {};
        if (url.indexOf("?") !== -1) {
            url.substr(1).split("&").forEach(function (item) {
                let array = item.split('=');
                param[array[0]] = unescape(array[1]);
            });
        }
        return param;
    },

    argsToArray: function (args) {
        let argsArray = [];
        for (let i = 0; i < args.length; i++) {
            argsArray.push(args[i]);
        }
        return argsArray;
    },

    preInsert(options) {
        const def = jQuery.Deferred();

        //分区域展示的字段
        if (options.fields && Gikam.isNotEmpty(options.fields) && Gikam.isNotEmpty(options.fields[0].fields)) {
            options.fields = options.fields.reduce((total, item) => {
                return total.concat(item.fields);
            }, []);
        }

        const fields = options.fields ? options.fields.filter(item => item.preInsert).map(item => {
            let copyItem = jQuery.extend(true, [], item);
            if (options.disableNotEmptyValidate !== true) {
                if (!copyItem.validators) {
                    copyItem.validators = [];
                }
                if (copyItem.validators.indexOf('notEmpty') === -1) {
                    copyItem.validators.push('notEmpty');
                }
            }
            copyItem.colspan = 1;
            return copyItem;
        }) : null;

        const insert = () => {
            modal && modal.window.showMask();
            //没有预新增字段直接新增
            Gikam.postText(options.url, Gikam.getJsonWrapper(form ? { t: getFieldInfoByData(form.getData()) } : null, ['', [Gikam.extend(form ? form.getData() : null, options.param)]])).done((id) => {
                modal && modal.close();
                modal && modal.window.closeMask();
                def.resolve(id);
            }).fail(() => {
                modal && modal.window.closeMask();
            });
        };

        //没有预新增字段，直接插入数据
        if (Gikam.isEmpty(fields)) {
            insert();
            return def;
        }

        const modal = Gikam.create('modal', {
            title: options.modalTitle,
            width: options.width || 400,
            height: options.height || 400
        });

        const layout = Gikam.create('layout', {
            renderTo: modal.window.$dom,
            center: {
                items: [{
                    type: 'btnToolbar',
                    items: [{
                        type: 'button',
                        text: '确认',
                        class: 'blue',
                        onClick() {
                            if (form.validate()) {
                                insert();
                            }
                        }
                    }, {
                        type: 'button',
                        text: '取消',
                        onClick() {
                            modal.close();
                        }
                    }
                    ]
                }]
            }
        });

        const form = Gikam.create('form', {
            renderTo: layout.options.center.$dom,
            columns: options.columns || 1,
            titleWidth: options.titleWidth || 80,
            fields: fields,
            autoSave: false
        });

        if (options.onFormRendered) {
            options.onFormRendered.apply(form);
        }

        const getFieldInfoByData = (data) => {
            const fieldInfo = {};
            form.options.fields.forEach(fieldOptions => {
                if (Gikam.isNotEmpty(data[fieldOptions.field], true) && ['select', 'simpleCheckbox'].indexOf(fieldOptions.type) > -1) {
                    const options = {
                        type: fieldOptions.type === 'simpleCheckbox' ? 'checkbox' : (fieldOptions.type || 'text'),
                    };
                    if (fieldOptions.type === 'select') {
                        options.items = fieldOptions.items;
                    }
                    fieldInfo[fieldOptions.field] = options;
                }
            });
            return fieldInfo;
        };

        return def;
    },

    error(message) {
        console.error('[Gikam error info]:' + message)
    },

    importExcel(options) {
        options.multiple = false;
        options.onAfterClose = (files) => {
            if (Gikam.isEmpty(files)) {
                return;
            }
            workspace.window.showMask();
            Gikam.post(Gikam.printf(options.url, {
                id: files[0].id
            })).done(function (result) {
                if (result.url) {
                    Gikam.download(result.url);
                } else if (result.message) {
                    Gikam.alert(result.message);
                }
                if (options.onImportSuccess) {
                    options.onImportSuccess.call(null, files);
                }
            }).always(function () {
                workspace.window.closeMask();
            });
        }
        Gikam.create('simpleUploader', options);
    },

    import(options) {
        this.importExcel(options);
    },

    /* 框架自定义配置,
        {
            Grid:{
                page : false
            }
        } 
    */
    setCompConfig(config) {
        for (let key in config) {
            Gikam.override(Gikam.component[Gikam.toInitialUpperCase(key)], { defaultOptions: config[key] });
        }
    },

    setDomAttribute(dom, attribute) {
        for (let key in attribute) {
            dom.setAttribute(key, attribute[key]);
        }
    },

    createDom(domTag, renderToDom) {
        const dom = document.createElement(domTag);
        renderToDom.appendChild(dom);
        return dom;
    },

    removeDom(dom) {
        dom.parentNode.removeChild(dom);
    },

    isString(str) {
        return typeof str === 'string';
    },

    /**
     * @description 清空组件数据方法，主要针对Form和Grid
     * @param {String} compIdArray 组件id集合
     * @returns
     */
    cleanCompData(compIdArray) {
        if (Gikam.isEmpty(compIdArray)) {
            return;
        }
        compIdArray.forEach((compId) => {
            const comp = Gikam.getComp(compId);
            if (comp) {
                comp.cleanData();
            }
        });
    },

    /**
     * @description 触发对象中的方法，并指定方法的上下文和参数
     * @private 
     * @param {Object} object 调用方法坐在的对象
     * @param {String} eventName 事件名称
     * @param {Object} scope 回调方法中的上下文
     * @param {*} args 回调方法中的参数
     */
    trigger(object, eventName, scope, ...args) {
        if (!object[eventName]) {
            return;
        }
        object[eventName].apply(scope, args);
    }


};






