import Base from '@/gikam/js/components/base';
import Gikam from '@/gikam/js/core/gikam-core';
import I18N from '@/gikam/js/components/I18N';
import Vue from 'vue/dist/vue.esm';
import homeVue from '../vue/home';

Gikam.component.I18N = I18N;

const defaultOptions = {
    logo: void 0,
    I18NUrl: void 0,
    //皮肤主题，选择范围green/blue
    skin: 'blue'
};

export default class HomePage extends Base {

    constructor(props) {
        super();
        this.initialize(props, defaultOptions).init();
    }

    init() {
        new I18N({
            url: this.options.I18NUrl,
            language: this.options.language
        }).done(() => {
            this.model = this.createViewModel();
        });
        this.initSystemInfo();
    }

    initSystemInfo() {
        document.title = this.options.title;
        if (this.options.xIconUrl) {
            const linkDom = document.createElement('link');
            Gikam.setDomAttribute(linkDom, {
                rel: 'icon',
                href: this.options.url
            });
            document.head.appendChild(linkDom);
        }
    }

    createViewModel() {
        const _this = this;
        const options = _this.options;
        new Vue({
            data() {
                return _this.options;
            },
            components: { homeVue },
            render() {
                return <home-vue
                    logo={options.logo}
                    skin={options.skin}>
                </home-vue>;
            }
        }).$mount(Gikam.createDom('div', document.body));
    }

    static setConfig(props) {
        Object.assign(defaultOptions, props);
    }
}




