<template>
    <div class="emc-home-index" :class="skin">
        <div class="language-switch" v-on:click="languageSwitch">
            <div class="language zh" :class="{active:language==='zh' || language==='zh-cn'}">中</div>
            <div class="language en" :class="{active:language==='en'}">En</div>
        </div>
        <div class="main">
            <div class="bg">
                <div class="sys-name">
                    <div class="title">
                        云服务
                        <span class="dot"></span>云端
                        <span class="dot"></span>实验室信息管理系统
                    </div>
                    <div class="sub-title">Laboratory Information Management System</div>
                </div>
            </div>
            <div class="login-container">
                <header class="logo-container" :style="{backgroundImage:logo?`url(${logo})`:null}"></header>
                <section class="login-form">
                    <div class="error-container" v-if="errorMessage">
                        <div class="error">
                            <span class="error-icon">
                                <infoImg v-bind="{width:'16px',height:'16px'}" />
                            </span>
                            {{errorMessage}}
                        </div>
                    </div>
                    <div class="login-mask" v-if="requesting"></div>
                    <div class="input-group" name="user">
                        <span class="input-group-addon user">
                            <userImg v-bind="{color: colorValue,width:'16px',height:'16px'}" />
                        </span>
                        <input placeholder="请输入用户名" v-model="user.name" @keydown.enter="login" />
                    </div>
                    <div class="input-group" name="pw">
                        <span class="input-group-addon lock">
                            <lockImg v-bind="{color: colorValue,width:'16px',height:'16px'}" />
                        </span>
                        <input
                            type="password"
                            placeholder="请输入密码"
                            v-model="user.password"
                            @keydown.enter="login"
                        />
                    </div>
                </section>
                <footer>
                    <div class="login-btn" :class="{requesting:requesting}" v-on:click="login">登录</div>
                </footer>
            </div>
        </div>
    </div>
</template>

<script>
import Gikam from "@/gikam/js/core/gikam-core";
import infoImg from "../../../gikam/js/components/template/img/info.vue";
import userImg from "../../../gikam/js/components/template/img/user.vue";
import lockImg from "../../../gikam/js/components/template/img/lock.vue";
import md5 from "../../../gikam/js/utils/md5";

export default {
    props: {
        logo: {
            type: String,
            default: null
        },
        skin: {
            type: String,
            default: "blue"
        }
    },

    components: {
        infoImg,
        userImg,
        lockImg
    },

    data() {
        return {
            errorMessage: null,
            language: "zh",
            requesting: false,
            user: {
                name: null,
                password: null
            }
        };
    },

    computed: {
        colorValue() {
            const color = { blue: "#007aff", green: "#27986d" };
            return color[this.skin];
        }
    },

    methods: {
        languageSwitch() {
            this.language = this.language === "zh" ? "en" : "zh";
        },

        validate() {
            if (!this.user.name) {
                this.errorMessage = "请输入用户名";
                return false;
            }
            if (!this.user.password) {
                this.errorMessage = "请输入密码";
                return false;
            }
            this.errorMessage = null;
            return true;
        },

        login() {
            if (this.validate() === false) {
                return;
            }
            this.requesting = true;
            Gikam.ajax({
                url: Gikam.IFM_CONTEXT + "/core/module/sys/login",
                type: "post",
                data: {
                    id: this.user.name,
                    password: md5(this.user.password)
                }
            })
                .done(() => {
                    location.href = "/module/index/workspaces";
                })
                .fail(r => {
                    this.requesting = false;
                    this.errorMessage = Gikam.propI18N(
                        JSON.parse(r.responseText).message
                    );
                });
        }
    }
};
</script>

<style>
html,
body {
    height: 100%;
    width: 100%;
    margin: 0;
    font-family: "Microsoft YaHei", Serif;
}

* {
    -moz-box-sizing: border-box;
    box-sizing: border-box;
}

input:focus {
    outline: none;
}

.language-switch {
    position: absolute;
    top: 32px;
    right: 32px;
    display: flex;
    border-radius: 4px;
    font-size: 12px;
    border: 1px solid #d9d9d9;
    overflow: hidden;
    cursor: pointer;
    user-select: none;
}

.language-switch > .language {
    width: 32px;
    height: 22px;
    display: -webkit-flex;
    display: -moz-box;
    display: -ms-flexbox;
    display: flex;
    align-items: center;
    justify-content: center;
    color: rgba(0, 0, 0, 0.45);
}

.language-switch > .language.active {
    background-color: #007aff;
    color: #fff;
}

.main {
    height: 384px;
    position: absolute;
    left: 0;
    right: 0;
    display: -webkit-flex;
    display: -moz-box;
    display: -ms-flexbox;
    display: flex;
    align-items: center;
    top: 50%;
    margin-top: -199px;
}

.bg {
    width: 100%;
    background-color: #0a4196;
    height: 256px;
    display: -webkit-flex;
    display: -moz-box;
    display: -ms-flexbox;
    display: flex;
    align-items: center;
}

.login-container {
    width: 364px;
    height: 384px;
    z-index: 1;
    background-color: #fff;
    right: 20%;
    position: absolute;
    border-radius: 4px;
    box-shadow: 0 5px 8px 0 rgba(0, 0, 0, 0.15);
    top: 0;
}

.logo-container {
    height: 80px;
    margin-bottom: 40px;
    background-image: url("../img/logo.png");
    background-repeat: no-repeat;
    background-position: center;
}

.login-form {
    width: 284px;
    margin: auto auto;
    padding-bottom: 32px;
}

.login-form .input-group {
    height: 48px;
    display: flex;
}

.login-form .input-group[name="user"] {
    margin-bottom: 32px;
}

.login-form .input-group[name="pw"] {
    margin-bottom: 22px;
}

.login-form .input-group .input-group-addon {
    display: block;
    width: 50px;
    height: 100%;
    background-position: center;
    background-repeat: no-repeat;
    margin-right: -50px;
    display: flex;
    justify-content: center;
    align-items: center;
}

.login-form input:not([type="checkbox"]) {
    width: 100%;
    height: 100%;
    border: none;
    background-color: transparent;
    flex: 1;
    font-size: 14px;
    color: #666;
    padding-left: 50px;
    border: 1px solid #d9d9d9;
    border-radius: 4px;
}

.login-form input:not([type="checkbox"]):focus {
    border-color: rgba(0, 122, 255, 0.5);
}

input::-webkit-input-placeholder {
    color: rgba(0, 0, 0, 0.15);
    font-size: 14px;
}

input::-moz-input-placeholder {
    color: rgba(0, 0, 0, 0.15) !important;
    font-size: 14px;
}

input:-ms-input-placeholder {
    color: rgba(0, 0, 0, 0.15) !important;
    font-size: 14px !important;
}

.auto-login-container input[type="checkbox"] {
    background-color: #fff;
    margin: 0 5px 0 0;
}

.login-form .quick-login {
    display: flex;
    justify-content: space-between;
    font-size: 12px;
    color: rgba(233, 188, 188, 0.45);
    padding: 0;
}

.login-form .quick-login .auto-login-container {
    display: flex;
    align-items: center;
    color: rgba(51, 51, 51, 0.45);
}

.login-form .quick-login .retrieve-pass {
    color: #007aff;
}

.login-btn {
    width: 264px;
    background-color: #0a4196;
    height: 36px;
    border-radius: 4px;
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: auto;
    font-size: 12px;
    cursor: pointer;
}

.login-btn.requesting {
    background-color: rgba(0, 0, 0, 0.2) !important;
    pointer-events: none;
}

.sys-name {
    padding-left: 96px;
}

.sys-name .title {
    font-size: 30px;
    color: #fff;
    display: flex;
    align-items: center;
}

.sys-name .sub-title {
    font-size: 14px;
    color: rgba(255, 255, 255, 0.3);
    margin-top: 24px;
}

.dot {
    background-color: #fff;
    border-radius: 50%;
    width: 10px;
    height: 10px;
    margin: 0 5px;
}

.login-form .select {
    border-bottom: 1px solid #d9d9d9;
}

.login-form .select.active {
    border-bottom-color: rgba(0, 122, 255, 0.5);
}

.login-form .select .icon svg {
    color: rgba(0, 0, 0, 0.4);
    font-size: 14px;
}

.login-form .select .select-container {
    border: none !important;
    padding-left: 50px;
    background-color: transparent;
}

.login-form .select .select-container .text {
    font-size: 14px;
    padding-left: 0;
}

.select .select-container .placeholder {
    padding-left: 0;
}

.select .select-container .icon {
    width: 50px;
}

[v-cloak] {
    display: none;
}

.error-container {
    position: absolute;
    top: 85px;
    left: 0;
    right: 0;
    display: flex;
    justify-content: center;
    color: red;
}

.error-container .error {
    height: 25px;
    width: 284px;
    background-color: rgba(255, 201, 201, 0.2);
    border: 1px solid #ff6e6e;
    color: #ff6e6e;
    font-size: 12px;
    display: flex;
    align-items: center;
    padding: 5px 10px;
}

.error-container .error .error-icon {
    display: block;
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
}

.combo-box-group .input-group-addon {
    margin-right: -50px;
}

.select-picker {
    margin-top: 2px;
}

.login-mask {
    position: absolute;
    top: 0;
    left: 0;
    bottom: 0;
    right: 0;
    z-index: 10;
}

/* 换肤-绿色 */
.emc-home-index.green .language-switch > .language.active {
    color: #fff;
}

.emc-home-index.green .language-switch > .language.active,
.emc-home-index.green .bg,
.emc-home-index.green .login-btn {
    background-color: #27986d;
}

/* 移动端适配 */
@media screen and (max-width: 1200px) and (min-width: 768px) {
    .sys-name .title {
        font-size: 18px;
    }
}

@media screen and (max-width: 768px) {
    .login-container {
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        margin: auto;
    }
    .sys-name {
        width: 100%;
        padding: 0;
        position: absolute;
        bottom: -200px;
    }
    .sys-name .title {
        font-size: 20px;
        color: #d9d9d9;
        display: flex;
        justify-content: center;
    }
    .sys-name .sub-title {
        color: #d9d9d9;
        display: flex;
        justify-content: center;
    }
}

@media screen and (max-width: 420px) {
    .main {
        width: 100%;
    }

    .bg {
        display: none;
    }

    .login-container {
        width: 100%;
        padding: 0 16px;
        box-shadow: none;
    }

    .sys-name {
        display: none;
    }

    .login-form input:not([type="checkbox"]) {
        border: none;
        border-bottom: 1px solid #d9d9d9;
        border-radius: 0;
    }

    .login-btn {
        width: 284px;
        font-size: 16px;
        background-color: #007aff;
    }

    .logo-container {
        background-size: 50%;
    }

    /*placeholder样式*/
    .login-form input::-webkit-input-placeholder {
        color: rgba(0, 0, 0, 0.85);
    }

    .login-form input::-moz-placeholder {
        color: rgba(0, 0, 0, 0.85);
    }

    .login-form input::-moz-placeholder {
        color: rgba(0, 0, 0, 0.85);
    }

    .login-form input::-ms-input-placeholder {
        color: rgba(0, 0, 0, 0.85);
    }

    .login-form .quick-login .auto-login-container {
        color: rgba(0, 0, 0, 0.65);
    }
}
</style>